INSERT OR IGNORE INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('4955cc05-f8de-5448-bcb3-e528430f560a', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'mcq', 'ক : খ = ৪ : ৭ এবং খ : গ = ১০ : ৭ হলে গ : খ : ক = কত?', '[{"id":"ক","text":"৪৯ : ৭০ : ৪০"},{"id":"খ","text":"৪৯ : ৪০ : ৭০"},{"id":"গ","text":"৪০ : ৭০ : ৪৯"},{"id":"ঘ","text":"৪০ : ৪৯ : ৭০"}]', 'ক', NULL, 'ক : খ = ৪ × ১০ : ৭ × ১০ = ৪০ : ৭০, খ : গ = ১০ × ৭ : ৭ × ৭ = ৭০ : ৪৯। তাই ক : খ : গ = ৪০ : ৭০ : ৪৯। প্রশ্ন চেয়েছে উল্টো ক্রমে, গ : খ : ক = ৪৯ : ৭০ : ৪০।', 'textbook_exercise', 40, NULL, NULL, 2, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'choice', 'আগে ক : খ : গ বের করো, তারপর প্রশ্নের ক্রম দেখো।', NULL, 'continued-ratio', '{"গ":"order-not-reversed","খ":"terms-mismatched","ঘ":"terms-mismatched"}', '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":2,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-2","printedPage":35}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z');
