INSERT OR IGNORE INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('567a714f-78ab-5d6a-9a97-332617ca1264', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'mcq', 'একজন কলাবিক্রেতা প্রতি হালি কলা ২৫ টাকা দরে ক্রয় করে প্রতি হালি ২৭ টাকা দরে বিক্রয় করলে, তাঁর ৫০ টাকা লাভ হয়। সে কত হালি কলা ক্রয় করেছিল?', '[{"id":"ক","text":"২৫ হালি"},{"id":"খ","text":"২০ হালি"},{"id":"গ","text":"৫০ হালি"},{"id":"ঘ","text":"২৭ হালি"}]', 'ক', NULL, 'প্রতি হালিতে লাভ ২৭ − ২৫ = ২ টাকা। মোট লাভ ৫০ টাকা, তাই হালি = ৫০ ÷ ২ = ২৫।', 'textbook_exercise', 40, NULL, NULL, 1, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'choice', 'প্রথমে এক হালিতে কত লাভ তা বের করো।', NULL, 'profit-loss', '{"গ":"total-as-count","ঘ":"price-as-count"}', '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":6,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-6","printedPage":35}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z');
INSERT OR IGNORE INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('4624130d-6b16-550b-aff0-de03ea0ca283', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'numeric', '৫ জন শ্রমিক ৬ দিনে ৮ বিঘা জমির ফসল উঠাতে পারে। ২০ বিঘা জমির ফসল উঠাতে ২৫ জন শ্রমিকের কত দিন লাগবে?', NULL, '3', NULL, '৫ জনের ৮ বিঘায় ৬ দিন লাগে। ১ জনের ১ বিঘায় লাগে ৬ × ৫ ÷ ৮ দিন। ২৫ জনের ২০ বিঘায় লাগে ৬ × ৫ × ২০ ÷ (৮ × ২৫) = ৩ দিন। বইয়ের উত্তর: ৩ দিনে।', 'textbook_exercise', 40, NULL, NULL, 2, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'number', 'আগে ১ জন শ্রমিক ১ বিঘায় কত দিন নেয় তা ভাবো।', 'দিন', 'unitary-work', NULL, '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":7,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-7","printedPage":35}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z');
INSERT OR IGNORE INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('5ef8481c-f79f-5a90-b0f7-b9925404d987', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'numeric', 'স্বপন একটি কাজ ২৪ দিনে করতে পারে। রতন উক্ত কাজ ১৬ দিনে করতে পারে। স্বপন ও রতন একত্রে কাজটি কত দিনে শেষ করতে পারবে?', NULL, '48/5', NULL, 'এক দিনে স্বপন করে কাজের ১/২৪ অংশ, রতন ১/১৬ অংশ। একত্রে ১/২৪ + ১/১৬ = ৫/৪৮ অংশ। পুরো কাজে লাগে ৪৮/৫ = ৯ ৩/৫ দিন। বইয়ের উত্তর: ৯ ৩/৫ দিনে।', 'textbook_exercise', 40, NULL, NULL, 2, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'number', 'একদিনে দুজন মিলে কাজের কত অংশ করে?', 'দিন', 'time-work', NULL, '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":8,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-8","printedPage":35}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z');
INSERT OR IGNORE INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('48e191d4-0f99-54fc-a453-1d3a8d4b754d', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'numeric', 'হাবিবা ও হালিমা একটি কাজ একত্রে ২০ দিনে করতে পারে। হাবিবা ও হালিমা একত্রে ৮ দিন কাজ করার পর হাবিবা চলে গেল। হালিমা বাকি কাজ ২১ দিনে শেষ করল। সম্পূর্ণ কাজটি হালিমা কত দিনে করতে পারত?', NULL, '35', NULL, '৮ দিনে দুজন মিলে করে ৮/২০ = ২/৫ অংশ। বাকি ৩/৫ অংশ হালিমা করে ২১ দিনে। তাই পুরো কাজ হালিমা একা করত ২১ ÷ ৩/৫ = ৩৫ দিনে। বইয়ের উত্তর: ৩৫ দিনে।', 'textbook_exercise', 40, NULL, NULL, 3, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'number', '৮ দিনে কাজের কত অংশ শেষ হয়েছিল?', 'দিন', 'time-work', NULL, '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":9,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-9","printedPage":35}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z');
INSERT OR IGNORE INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('52d972b2-246c-57f8-a529-f191f76013ef', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'numeric', 'একটি চৌবাচ্চায় দুটি নল আছে। প্রথম ও দ্বিতীয় নল দ্বারা যথাক্রমে ১২ ঘণ্টা ও ১৮ ঘণ্টায় খালি চৌবাচ্চাটি পূর্ণ হয়। দুটি নল এক সাথে খুলে দিলে খালি চৌবাচ্চাটি কত ঘণ্টায় পূর্ণ হবে?', NULL, '36/5', NULL, 'এক ঘণ্টায় ১/১২ + ১/১৮ = ৫/৩৬ অংশ পূর্ণ হয়। তাই লাগে ৩৬/৫ = ৭ ১/৫ ঘণ্টা। বইয়ের উত্তর: ৭ ১/৫ ঘণ্টায়।', 'textbook_exercise', 41, NULL, NULL, 2, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'number', 'এক ঘণ্টায় দুটি নল মিলে কত অংশ ভরে?', 'ঘণ্টা', 'pipes', NULL, '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":12,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-12","printedPage":36}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z');
INSERT OR IGNORE INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('11f5525b-ed76-553b-928c-faef681b5dcb', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'numeric', 'স্রোতের অনুকূলে একটি নৌকা ৪ ঘণ্টায় ৩৬ কি.মি. পথ অতিক্রম করে। স্রোতের বেগ প্রতি ঘণ্টায় ৩ কি.মি. হলে, স্থির পানিতে নৌকার বেগ কত?', NULL, '6', NULL, 'অনুকূলে বেগ = ৩৬ ÷ ৪ = ৯ কি.মি./ঘণ্টা = নৌকার বেগ + স্রোতের বেগ। তাই নৌকার বেগ = ৯ − ৩ = ৬ কি.মি./ঘণ্টা। বইয়ের উত্তর: ৬ কি.মি./ঘণ্টা।', 'textbook_exercise', 41, NULL, NULL, 2, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'number', 'অনুকূলে চললে স্রোতের বেগ যোগ হয়।', 'কি.মি./ঘণ্টা', 'boat-stream', NULL, '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":13,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-13","printedPage":36}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z');
INSERT OR IGNORE INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('2be9c195-4625-528f-8501-2505061422bf', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'numeric', 'স্রোতের প্রতিকূলে একটি জাহাজ ১১ ঘণ্টায় ৭৭ কি.মি. পথ অতিক্রম করে। স্থির পানিতে জাহাজের গতিবেগ প্রতি ঘণ্টায় ৯ কি.মি. হলে, স্রোতের গতিবেগ প্রতি ঘণ্টায় কত?', NULL, '2', NULL, 'প্রতিকূলে বেগ = ৭৭ ÷ ১১ = ৭ কি.মি./ঘণ্টা = জাহাজের বেগ − স্রোতের বেগ। তাই স্রোতের বেগ = ৯ − ৭ = ২ কি.মি./ঘণ্টা। বইয়ের উত্তর: ২ কি.মি./ঘণ্টা।', 'textbook_exercise', 41, NULL, NULL, 2, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'number', 'প্রতিকূলে চললে স্রোতের বেগ বিয়োগ হয়।', 'কি.মি./ঘণ্টা', 'boat-stream', NULL, '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":14,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-14","printedPage":36}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z');
INSERT OR IGNORE INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('f75699a7-7375-5ab4-8342-82ed790110b6', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'numeric', 'লিলি একা একটি কাজ ১০ ঘণ্টায় করতে পারেন। মিলি একা ঐ কাজটি ৮ ঘণ্টায় করতে পারেন। লিলি ও মিলি একত্রে ঐ কাজটি কত ঘণ্টায় করতে পারবেন?', NULL, '40/9', NULL, 'এক ঘণ্টায় ১/১০ + ১/৮ = ৯/৪০ অংশ। তাই লাগে ৪০/৯ = ৪ ৪/৯ ঘণ্টা। বইয়ের উত্তর: ৪ ৪/৯ ঘণ্টায়।', 'textbook_exercise', 41, NULL, NULL, 2, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'number', 'দুজনের এক ঘণ্টার কাজ যোগ করো।', 'ঘণ্টা', 'time-work', NULL, '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":16,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-16","printedPage":36}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z');
INSERT OR IGNORE INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('a3467742-ebee-560e-9bf7-28769e4d7478', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'numeric', '১০০ মিটার দীর্ঘ একটি ট্রেনের গতিবেগ ঘণ্টায় ৪৮ কিলোমিটার। ঐ ট্রেনটি ৩০ সেকেন্ডে একটি সেতু অতিক্রম করে। সেতুটির দৈর্ঘ্য কত?', NULL, '300', NULL, '৪৮ কি.মি./ঘণ্টা = ৪৮০০০ ÷ ৩৬০০ মিটার/সেকেন্ড। ৩০ সেকেন্ডে যায় ৪৮০০০ × ৩০ ÷ ৩৬০০ = ৪০০ মিটার। এর মধ্যে ট্রেনের দৈর্ঘ্য ১০০ মিটার, তাই সেতু ৩০০ মিটার। বইয়ের উত্তর: ৩০০ মিটার।', 'textbook_exercise', 41, NULL, NULL, 3, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'number', 'সেতু পার হতে ট্রেনকে নিজের দৈর্ঘ্যও যেতে হয়।', 'মিটার', 'train-speed', NULL, '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":18,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-18","printedPage":36}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z');
INSERT OR IGNORE INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('9d67fc4b-ce51-5b36-96cf-281da6f8d024', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'numeric', '১২০ মিটার দীর্ঘ একটি ট্রেন ৩৩০ মিটার দীর্ঘ একটি সেতু অতিক্রম করবে। ট্রেনটির গতিবেগ ঘণ্টায় ৩০ কি.মি. হলে, সেতুটি অতিক্রম করতে ট্রেনটির কত সময় লাগবে?', NULL, '54', NULL, 'মোট পথ ১২০ + ৩৩০ = ৪৫০ মিটার। ৩০ কি.মি./ঘণ্টা = ৩০০০০ ÷ ৩৬০০ = ২৫/৩ মিটার/সেকেন্ড। সময় = ৪৫০ ÷ ২৫/৩ = ৫৪ সেকেন্ড। বইয়ের উত্তর: ৫৪ সেকেন্ড।', 'textbook_exercise', 41, NULL, NULL, 3, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'number', 'ট্রেনের দৈর্ঘ্য আর সেতুর দৈর্ঘ্য যোগ করো।', 'সেকেন্ড', 'train-speed', NULL, '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":19,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-19","printedPage":36}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z');
INSERT OR IGNORE INTO questions (id, chapter_id, type, prompt, options, answer, tolerance, explanation, source, source_page, objective_id, bloom, difficulty, language, status, created_by, created_at, review_status, answer_kind, hint, unit, skill, misconceptions, provenance, reviewed_by, reviewed_at, published_by, published_at, updated_at) VALUES ('10d881f3-32e3-5dcc-b227-0058bd2baa8c', 'f9c3f216-a09e-5c02-979e-497b60f8333a', 'short', 'তামা, দস্তা ও রুপা মিশিয়ে একটি গহনা তৈরি করা হলো। ঐ গহনায় তামা ও দস্তার অনুপাত ১ : ২ এবং দস্তা : রুপার অনুপাত ৩ : ৫। গহনার ওজন ১৯০ গ্রাম।
(ক) তামা, দস্তা ও রুপার অনুপাত নির্ণয় করো।', NULL, '3:6:10', NULL, '১ : ২ = ৩ : ৬ এবং ৩ : ৫ = ৬ : ১০, তাই তামা : দস্তা : রুপা = ৩ : ৬ : ১০। মোট ১৯ ভাগে ১৯০ গ্রাম, এক ভাগ ১০ গ্রাম: তামা ৩০, দস্তা ৬০, রুপা ১০০ গ্রাম। তামা ৩০ গ্রামের জন্য ১ : ৩ হলে দস্তা লাগে ৯০ গ্রাম, তাই আরও ৩০ গ্রাম দস্তা। বইয়ের উত্তর: (ক) ৩ : ৬ : ১০ (খ) ৩০, ৬০, ১০০ গ্রাম (গ) ৩০ গ্রাম।', 'textbook_exercise', 41, NULL, NULL, 3, 'bn', 'published', 'educerro-seed', '2026-10-26T00:00:00Z', 'published', 'ratio', 'আগে দুটি অনুপাতকে ধারাবাহিক অনুপাতে আনো।', NULL, 'continued-ratio', NULL, '{"origin":"textbook-key","exercise":"অনুশীলনী ২.৩","number":20,"answerFrom":"The book''s answer key, printed page 171","checkedBy":"Claude (Educerro build), against the page image and the answer key; not yet reviewed by a teacher","key":"m23-20a","printedPage":36}', 'educerro-seed', '2026-10-26T00:00:00Z', 'educerro-seed', '2026-10-26T00:00:00Z', '2026-10-26T00:00:00Z');
